timeout 40 sshpass -p 'Zjlab@X10000' ssh -p 30001 -o StrictHostKeyChecking=no root@192.168.4.127 'bash -lc "
echo ===== pip versions =====;
pip show vllm 2>/dev/null | grep -E \"^Name|^Version|^Location\";
echo ---;
pip show torch_musa torch-musa 2>/dev/null | grep -E \"^Name|^Version|^Location\";
echo ---;
pip show torch 2>/dev/null | grep -E \"^Name|^Version\";
echo ===== python import =====;
python3 -c \"import vllm; print(\\\"vllm\\\", vllm.__version__, vllm.__file__)\" 2>&1 | head -3;
python3 -c \"import torch_musa; print(\\\"torch_musa\\\", getattr(torch_musa,\\\"__version__\\\",\\\"?\\\"))\" 2>&1 | head -3;
"' 2>&1 | head -40

timeout 60 sshpass -p 'Zjlab@X10000' ssh -p 30001 -o StrictHostKeyChecking=no root@192.168.4.127 'bash -lc "
echo ===== which vllm =====;
which vllm 2>/dev/null; head -1 \$(which vllm) 2>/dev/null;
echo ===== find vllm dist-info / egg-link =====;
find / -maxdepth 7 \( -name \"vllm-*.dist-info\" -o -name \"vllm.egg-link\" -o -name \"vllm.egg-info\" \) 2>/dev/null | head;
echo ===== find vllm package dirs (version.py) =====;
find / -maxdepth 8 -path \"*/vllm/version.py\" 2>/dev/null | head;
find / -maxdepth 8 -path \"*/vllm/__init__.py\" 2>/dev/null | head;
echo ===== likely source repos =====;
ls -d /vllm* /workspace/vllm* /home/vllm* /opt/vllm* /root/vllm* 2>/dev/null;
"' 2>&1 | head -50

timeout 40 sshpass -p 'Zjlab@X10000' ssh -p 30001 -o StrictHostKeyChecking=no root@192.168.4.127 'bash -lc "
echo ===== which vllm =====;
which vllm; readlink -f \$(which vllm) 2>/dev/null;
echo ===== head of vllm launcher =====;
head -3 \$(which vllm) 2>/dev/null;
echo ===== dist-packages vllm =====;
ls -d /usr/local/lib/python3.10/dist-packages/vllm* 2>/dev/null;
echo ===== common src dirs =====;
ls -d /workspace /opt /root /home 2>/dev/null;
ls /workspace 2>/dev/null; echo --opt--; ls /opt 2>/dev/null; echo --root--; ls /root 2>/dev/null;
"' 2>&1 | head -50

timeout 45 sshpass -p 'Zjlab@X10000' ssh -p 30001 -o StrictHostKeyChecking=no root@192.168.4.127 'bash -lc "
echo ===== am I in a container? =====;
ls -la /.dockerenv 2>/dev/null && echo IN_CONTAINER || echo NO_dockerenv;
echo ===== docker available? =====;
which docker >/dev/null 2>&1 && docker ps --format \"{{.Names}}\t{{.Image}}\" 2>&1 | head || echo no-docker-cli;
echo ===== /home contents =====;
ls /home 2>/dev/null | head -30;
echo ===== /mnt =====;
ls /mnt 2>/dev/null;
echo ===== search vllm in dist-packages (all py) =====;
ls /usr/local/lib/python3*/dist-packages/ 2>/dev/null | grep -i vllm;
ls /usr/lib/python3*/dist-packages/ 2>/dev/null | grep -i vllm;
echo ===== pip3 freeze grep vllm =====;
pip3 freeze 2>/dev/null | grep -i vllm;
"' 2>&1 | head -60

timeout 45 sshpass -p 'Zjlab@X10000' ssh -p 30001 -o StrictHostKeyChecking=no root@192.168.4.127 'bash -lc "
echo ===== /home/dist =====;
ls -la /home/dist 2>/dev/null | head -30;
echo ===== conda envs =====;
ls /opt/conda/envs 2>/dev/null; which conda 2>/dev/null;
echo ===== vllm in any dist-packages =====;
find /usr /opt -maxdepth 5 -name version.py -path \"*vllm*\" 2>/dev/null | head;
find /usr /opt -maxdepth 5 -name vllm -type d 2>/dev/null | head;
echo ===== head of nohup log =====;
head -20 /home/run_list.nohup.log 2>/dev/null;
"' 2>&1 | head -60

timeout 50 sshpass -p 'Zjlab@X10000' ssh -p 30001 -o StrictHostKeyChecking=no root@192.168.4.127 'bash -lc "
echo ===== /mnt/si0003568lza =====;
ls /mnt/si0003568lza 2>/dev/null;
echo ===== default dir =====;
ls /mnt/si0003568lza/default 2>/dev/null;
echo ===== models dir =====;
ls /mnt/si0003568lza/default/models 2>/dev/null | head -30;
echo ===== search vllm under /mnt/si0003568lza =====;
find /mnt/si0003568lza -maxdepth 6 -name version.py -path \"*vllm*\" 2>/dev/null | head;
find /mnt/si0003568lza -maxdepth 5 -type d -name vllm 2>/dev/null | head;
echo ===== venvs =====;
find /mnt/si0003568lza -maxdepth 4 -name activate -path \"*bin*\" 2>/dev/null | head;
"' 2>&1 | head -60

timeout 60 sshpass -p 'Zjlab@X10000' ssh -p 30001 -o StrictHostKeyChecking=no root@192.168.4.127 'bash -lc "
echo ===== pip show vllm =====;
pip show vllm 2>&1 | grep -iE \"name|version|location\" | head;
echo ===== all python3 on PATH =====;
ls -la /usr/bin/python3* /usr/local/bin/python3* 2>/dev/null;
echo ===== find vllm version.py (bounded) =====;
timeout 40 find /usr/local/lib /usr/lib /mnt/si0003568lza/default/models -maxdepth 6 -path \"*vllm/version.py\" 2>/dev/null | head;
echo ===== find any vllm dir under models =====;
timeout 40 find /mnt/si0003568lza/default/models -maxdepth 3 -iname \"*vllm*\" 2>/dev/null | head -20;
"' 2>&1 | head -50

timeout 70 sshpass -p 'Zjlab@X10000' ssh -p 30001 -o StrictHostKeyChecking=no root@192.168.4.127 'bash -lc "
echo ===== find vllm version.py bounded =====;
timeout 50 find /usr/local/lib /usr/lib /mnt/si0003568lza/default/models -maxdepth 7 -path \"*vllm/version.py\" 2>/dev/null | head;
echo ===== find vllm dirs under models =====;
timeout 50 find /mnt/si0003568lza/default/models -maxdepth 3 -iname \"*vllm*\" 2>/dev/null | head -20;
echo ===== contents of models dir grep vllm =====;
ls /mnt/si0003568lza/default/models 2>/dev/null | grep -i vllm;
"' 2>&1 | head -40

timeout 80 sshpass -p 'Zjlab@X10000' ssh -p 30001 -o StrictHostKeyChecking=no root@192.168.4.127 'bash -lc "
echo ===== site-packages paths =====;
python3 -c \"import site,sys; print(site.getsitepackages()); print(sys.prefix)\";
echo ===== pip list grep vllm/mate/musa =====;
pip list 2>/dev/null | grep -iE \"vllm|mate|musa|torch\";
echo ===== ls dist-packages grep vllm/mate =====;
ls /usr/local/lib/python3.10/dist-packages/ 2>/dev/null | grep -iE \"vllm|mate\";
echo ===== musa toolkit version =====;
cat /usr/local/musa/version.json 2>/dev/null | head -20;
ls -d /usr/local/musa* 2>/dev/null;
echo ===== mtt smi =====;
mthreads-gmi -q 2>/dev/null | grep -iE \"driver|cuda|version\" | head;
"' 2>&1 | head -60

timeout 70 sshpass -p 'Zjlab@X10000' ssh -p 30001 -o StrictHostKeyChecking=no root@192.168.4.127 'bash -lc "
echo ===== mate package top-level =====;
ls /usr/local/lib/python3.10/dist-packages/mate 2>/dev/null | head -40;
echo ===== vllm inside mate? =====;
ls -d /usr/local/lib/python3.10/dist-packages/mate/*vllm* 2>/dev/null;
find /usr/local/lib/python3.10/dist-packages/mate -maxdepth 2 -iname \"*vllm*\" 2>/dev/null | head;
echo ===== entry points / console scripts =====;
cat /usr/local/lib/python3.10/dist-packages/mate-0.1.3+mu436torch2.9.dist-info/entry_points.txt 2>/dev/null;
echo ===== any vllm executable anywhere on PATH dirs =====;
ls /usr/local/bin 2>/dev/null | grep -iE \"vllm|mate\";
echo ===== mate version attr =====;
python3 -c \"import mate; print(getattr(mate,\\\"__version__\\\",\\\"?\\\"), mate.__file__)\" 2>&1 | head -5;
"' 2>&1 | head -60

timeout 80 sshpass -p 'Zjlab@X10000' ssh -p 30001 -o StrictHostKeyChecking=no root@192.168.4.127 'bash -lc "
echo ===== mate version.py =====;
cat /usr/local/lib/python3.10/dist-packages/mate/version.py 2>/dev/null | head;
echo ===== quick bounded search for vllm source repo =====;
timeout 50 find /home /root /workspace /opt /mnt/si0003568lza/default/models -maxdepth 4 -type d -name vllm 2>/dev/null | head;
echo ===== search vllm setup/pyproject bounded =====;
timeout 20 find /home /root -maxdepth 5 -iname \"*vllm*\" 2>/dev/null | head;
echo ===== pip list full count =====;
pip list 2>/dev/null | wc -l;
"' 2>&1 | head -40

timeout 80 sshpass -p 'Zjlab@X10000' ssh -p 30001 -o StrictHostKeyChecking=no root@192.168.4.127 'bash -lc "
for V in sglang-0.5.6 triton-3.2.0; do
  echo ========== venv: \$V ==========;
  PY=/root/.virtualenvs/\$V/bin/python;
  \$PY -m pip show vllm 2>/dev/null | grep -iE \"^Name|^Version|^Location|^Editable\";
  echo --- vllm __file__ ---;
  \$PY -c \"import vllm,os; print(vllm.__version__); print(vllm.__file__)\" 2>&1 | head -4;
done;
echo ===== list venvs =====;
ls /root/.virtualenvs 2>/dev/null;
"' 2>&1 | head -50

timeout 80 sshpass -p 'Zjlab@X10000' ssh -p 30001 -o StrictHostKeyChecking=no root@192.168.4.127 'bash -lc "
echo ===== site-packages vllm has source? =====;
ls /root/.virtualenvs/sglang-0.5.6/lib/python3.10/site-packages/vllm/*.py 2>/dev/null | head -5;
echo -n \"py file count: \"; find /root/.virtualenvs/sglang-0.5.6/lib/python3.10/site-packages/vllm -name \"*.py\" 2>/dev/null | wc -l;
echo ===== is it editable install? =====;
cat /root/.virtualenvs/sglang-0.5.6/lib/python3.10/site-packages/vllm-*.dist-info/direct_url.json 2>/dev/null;
ls /root/.virtualenvs/sglang-0.5.6/lib/python3.10/site-packages/__editable__*vllm* 2>/dev/null;
echo ===== standalone vllm git repo? =====;
timeout 40 find /root /home /mnt/si0003568lza/default/models -maxdepth 4 -type d -name .git -path \"*vllm*\" 2>/dev/null | head;
echo ===== running vllm processes =====;
ps -ef 2>/dev/null | grep -iE \"vllm|venv\" | grep -v grep | head;
"' 2>&1 | head -50

