    ws=wb[name]
    model=deploy=io=None; data={}
    for r in range(3, ws.max_row+1):
        a=ws.cell(r,1).value; b=ws.cell(r,2).value; c=ws.cell(r,3).value
        m=ws.cell(r,13).value; w=ws.cell(r,23).value
        if a not in (None,''): model=str(a).strip()
        if b not in (None,''): deploy=str(b).strip().replace(chr(10),' ')
        if c not in (None,''): io=str(c).strip()
        if not (model and deploy): continue
        if not tp1_match(deploy): continue
        key=model
        d=data.setdefault(key, {'deploy':deploy,'path':None,'cases':{}})
        if w and 'MODEL_PATH' in str(w):
