import ast, sys, builtins

def check(path):
    src = open(path).read()
    tree = ast.parse(src)
    # 模块级名字:赋值、函数/类定义、import
    module_names = set(dir(builtins))
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            module_names.add(node.name)
        elif isinstance(node, ast.Import):
            for a in node.names:
                module_names.add((a.asname or a.name).split('.')[0])
        elif isinstance(node, ast.ImportFrom):
            for a in node.names:
                module_names.add(a.asname or a.name)
    # 模块级直接赋值(顶层)
    for node in tree.body:
        if isinstance(node, ast.Assign):
            for t in ast.walk(node):
                if isinstance(t, ast.Name) and isinstance(t.ctx, ast.Store):
                    module_names.add(t.id)

    issues = []
    def collect_assigned(fn):
        names = set()
        for n in fn.args.args + fn.args.posonlyargs + fn.args.kwonlyargs:
            names.add(n.arg)
        if fn.args.vararg: names.add(fn.args.vararg.arg)
        if fn.args.kwarg: names.add(fn.args.kwarg.arg)
        for node in ast.walk(fn):
            if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store):
                names.add(node.id)
            elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node is not fn:
                names.add(node.name)
            elif isinstance(node, (ast.Import, ast.ImportFrom)):
                for a in node.names:
                    names.add(a.asname or a.name.split('.')[0])
            elif isinstance(node, ast.comprehension):
                for t in ast.walk(node.target):
                    if isinstance(t, ast.Name): names.add(t.id)
            elif isinstance(node, (ast.With, ast.AsyncWith)):
                for item in node.items:
                    if item.optional_vars:
                        for t in ast.walk(item.optional_vars):
                            if isinstance(t, ast.Name): names.add(t.id)
            elif isinstance(node, ast.ExceptHandler) and node.name:
                names.add(node.name)
        return names

    for fn in [n for n in ast.walk(tree) if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))]:
        local = collect_assigned(fn)
        for node in ast.walk(fn):
            if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Load):
                nm = node.id
                if nm not in local and nm not in module_names:
                    issues.append((fn.name, node.lineno, nm))
    return issues

