import ast, sys, builtins

def module_globals(tree):
    g = set(dir(builtins))
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            g.add(node.name)
        elif isinstance(node, ast.Import):
            for a in node.names: g.add((a.asname or a.name).split('.')[0])
        elif isinstance(node, ast.ImportFrom):
            for a in node.names: g.add(a.asname or a.name)
    # 顶层 Assign / AnnAssign / AugAssign,含 if/else/for/with/try 里的模块级
    class TopStore(ast.NodeVisitor):
        def __init__(self): self.depth_fn=0
        def visit_FunctionDef(self,n): self.depth_fn+=1; self.generic_visit(n); self.depth_fn-=1
        visit_AsyncFunctionDef=visit_FunctionDef
        def visit_ClassDef(self,n): self.depth_fn+=1; self.generic_visit(n); self.depth_fn-=1
        def visit_Name(self,n):
            if self.depth_fn==0 and isinstance(n.ctx, ast.Store): g.add(n.id)
    TopStore().visit(tree)
    return g

def assigned_in(fn):
    names=set()
    for n in fn.args.args+fn.args.posonlyargs+fn.args.kwonlyargs: names.add(n.arg)
    if fn.args.vararg: names.add(fn.args.vararg.arg)
    if fn.args.kwarg: names.add(fn.args.kwarg.arg)
    for node in ast.walk(fn):
        if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store): names.add(node.id)
        elif isinstance(node,(ast.FunctionDef,ast.AsyncFunctionDef)) and node is not fn: names.add(node.name)
        elif isinstance(node,(ast.Import,ast.ImportFrom)):
            for a in node.names: names.add(a.asname or a.name.split('.')[0])
        elif isinstance(node, ast.ExceptHandler) and node.name: names.add(node.name)
    return names

def check(path):
    tree=ast.parse(open(path).read()); g=module_globals(tree); issues=[]
    # 为每个函数算"自身+所有外层函数"的可见名字
    def walk_fn(fn, enclosing):
        local=assigned_in(fn); visible=enclosing|local|g
        for node in ast.iter_child_nodes(fn):
            scan(node, fn, visible)
        for sub in [n for n in ast.walk(fn) if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)) and n is not fn]:
            # 只处理直接嵌套(避免重复);简单起见全部用 enclosing|local
            pass
    def scan(node, fn, visible):
        for n in ast.walk(node):
            if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)):
                inner=assigned_in(n)
                for c in ast.iter_child_nodes(n): scan(c, n, visible|inner)
                return
            if isinstance(n, ast.Name) and isinstance(n.ctx, ast.Load):
                if n.id not in visible: issues.append((fn.name,n.lineno,n.id))
    for fn in [n for n in tree.body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef))]:
        walk_fn(fn, set())
    return sorted(set(issues))

for p in sys.argv[1:]:
    iss=check(p); print(f"=== {p} ===")
    print("  OK" if not iss else "")
    for fn,ln,nm in iss: print(f"  行{ln} {fn}(): '{nm}'")
