                        f"{metric(pf, M_WAIT):.0f}", f"{metric(pf, M_RUN):.0f}",
                        f"{metric(dec, M_WAIT):.0f}", f"{metric(dec, M_RUN):.0f}",
                        f"{metric_kv(dec)*100:.0f}",
                        f"{avg(u[0:4]):.0f}", f"{avg(u[4:8]):.0f}"])
            f.flush()
            time.sleep(INTERVAL)


def summary(csv_path):
